fn main() {
    let input = Some("42");
    let parsed: Result<Option<u16>, _> =
        input.map(str::parse::<u16>).transpose();
    assert_eq!(parsed, Ok(Some(42)));
    let absent: Option<&str> = None;
    assert_eq!(
        absent.map(str::parse::<u16>).transpose(),
        Ok(None)
    );
}

